CREATE TABLE public.account_status(user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.account_status TO authenticated; GRANT ALL ON public.account_status TO service_role;
ALTER TABLE public.account_status ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own account status" ON public.account_status FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.is_platform_admin());
CREATE FUNCTION public.account_is_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.account_status WHERE user_id=auth.uid() AND status<>'active'); $$;
REVOKE ALL ON FUNCTION public.account_is_active() FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.account_is_active() TO authenticated,service_role;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['profiles','user_roles','institutions','institution_memberships','courses','modules','lessons','learning_materials','lesson_notes','enrollments','lesson_progress','quizzes','quiz_questions','quiz_question_options','quiz_attempts','assignments','assignment_submissions','payments','certificates','live_classes','announcements','academic_years','classes','attendance_sessions','attendance_records','notifications','direct_messages','institution_subscriptions','institution_audit_logs','issues','roles','user_assigned_roles','user_permission_overrides','rbac_audit_logs','departments'] LOOP EXECUTE format('CREATE POLICY "Active account required" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING(public.account_is_active()) WITH CHECK(public.account_is_active())',t); END LOOP; END $$;